<?php
/**
 * Slice 9 proof 2 — the Curate area: the index and its counts; ownership (the leavers, the form, a transfer limited to one library and a full one, the walls, the level it changes, the notice to the new owner, the refusals in words);
 * the storage report (its numbers against the database's own, the duplicates' waste, the disk, the CSV); the search report (the empty searches clustered, the top queries, a day, keyword against graph).
 */
require __DIR__ . '/lib.php';
require_once dirname(__DIR__, 3) . '/app/features/curate/write.php';
$w = world9();
$p = pdo();
$leeLive = static fn (): int => (int) one('SELECT count(*) FROM documents WHERE owner_member_id = 31');

echo "1. The index\n";
$r = get_json(27, '/curate/');
$c = $r['json']['data']['counts'] ?? [];
ok($r['code'] === 200 && array_keys($c) === ['groups', 'shared_libraries', 'tags', 'rules', 'ownership', 'storage_bytes', 'search_gaps', 'proposals'], 'a curator\'s /curate/: 200 with the eight counts');
as_member(27);
ok($c['groups'] === (int) one('SELECT count(*) FROM mcp_groups WHERE archived_at IS NULL') && $c['shared_libraries'] === (int) one("SELECT count(*) FROM mcp_libraries WHERE kind = 'shared' AND archived_at IS NULL"), 'groups and shared libraries counted as the views count them');
ok($c['ownership'] === 1 && $c['storage_bytes'] === (int) one('SELECT sum(used_bytes) FROM libraries WHERE archived_at IS NULL'), 'one leaver holds documents; the storage is the libraries\' used bytes added up');
ok($c['search_gaps'] === 2 && $c['tags'] > 0, 'two searches found nothing in 30 days (clustered); tags counted');
$h = page(actor(27), '/curate/')['body'];
$miss = missing_ids($h, ['curate-index', 'curate-card-groups', 'curate-card-shared-libraries', 'curate-card-tags', 'curate-card-ownership', 'curate-card-storage', 'curate-card-search', 'curate-card-proposals', 'curate-count-ownership']);
ok($miss === [], 'the page: a card for each of the seven, each with its count' . ($miss ? ' — missing ' . implode(', ', $miss) : ''));
foreach (['/groups/', '/libraries/?kind=shared', '/tags/', '/curate/ownership', '/curate/storage', '/curate/search', '/curate/proposals'] as $u) { ok(str_contains($h, 'href="' . $u . '"') && page(actor(27), $u)['code'] === 200, "the card links to $u and it opens"); }
ok(page(actor(1), '/curate/')['code'] === 200 && get_json(26, '/curate/')['code'] === 403 && get_json(29, '/curate/')['code'] === 403, 'the admin 200; a Member (Priya) and a guest (Ann) 403');
$x = req('GET', '/curate/', ['headers' => ['Accept: application/json']]);
ok($x['code'] === 401, 'no session, JSON: 401');
$since = last_activity_id(); page(actor(27), '/curate/');
ok(count(activity('screen.view', $since)) === 1 && activity('screen.view', $since)[0]['screen'] === 'curate', 'screen.view logged for curate');

echo "2. Ownership: the screen\n";
$r = get_json(27, '/curate/ownership');
$j = $r['json']['data'] ?? [];
ok($r['code'] === 200 && count($j['leavers'] ?? []) === 1 && $j['leavers'][0]['member_id'] === 31 && $j['leavers'][0]['status'] === 'inactive', 'a curator sees Lee, who left');
as_member(27);
$sql = q('SELECT documents, live_bytes FROM dc_storage_by_owner(500) WHERE member_id = 31')[0];
ok($j['leavers'][0]['documents'] === (int) $sql['documents'] && $j['leavers'][0]['documents'] === 12 && $j['leavers'][0]['live_bytes'] === (int) $sql['live_bytes'], 'his twelve documents and their bytes are dc_storage_by_owner\'s own');
$h = page(actor(27), '/curate/ownership')['body'];
ok(missing_ids($h, ['ownership-leavers', 'ownership-leaver-31', 'ownership-pick-31', 'ownership-choose', 'ownership-choose-form', 'ownership-member-picker']) === [] && !str_contains($h, 'id="ownership-form"'), 'the page: the leavers, the picker for anyone else; no transfer form yet');
ok(get_json(26, '/curate/ownership')['code'] === 403 && get_json(29, '/curate/ownership')['code'] === 403, 'a Member and a guest: 403');
$r = get_json(27, '/curate/ownership?member=31');
ok(($r['json']['data']['owner']['documents'] ?? 0) === 12 && $r['json']['data']['owner']['display_name'] === 'SMOKE Lee', 'with ?member=31: twelve documents to hand over');
$r = get_json(27, '/curate/ownership?member=31&library=' . $w['lee_lib']);
ok(($r['json']['data']['owner']['documents'] ?? 0) === 4 && $r['json']['data']['library_id'] === $w['lee_lib'], '...four when limited to his own library');
$h = page(actor(27), '/curate/ownership?member=31&library=' . $w['lee_lib'])['body'];
ok(missing_ids($h, ['ownership-form', 'ownership-transfer-form', 'ownership-newowner-picker', 'ownership-library-picker', 'ownership-transfer-btn', 'ownership-count']) === [] && str_contains($h, 'hx-confirm="Hand 4 documents of SMOKE Lee'), 'the form: the new owner, the library, and a confirm that names the count (4)');
ok(get_json(27, '/curate/ownership?member=999999')['code'] === 404, 'a person who does not exist: 404');

echo "3. Ownership: the refusals, in words\n";
$before = $leeLive();
$rows = fn (array $f) => post_json(27, '/curate/ownership/transfer.php', $f);
$x = post_json(26, '/curate/ownership/transfer.php', ['owner' => 31, 'new_owner' => 28]);
ok($x['code'] === 403 && str_contains($x['body'], 'transfer ownership'), 'a Member: 403 "You may not transfer ownership."');
$x = post_json(29, '/curate/ownership/transfer.php', ['owner' => 31, 'new_owner' => 28]);
ok($x['code'] === 403, 'a guest: 403');
$x = req('POST', '/curate/ownership/transfer.php', ['headers' => ['Accept: application/json'], 'form' => ['owner' => 31, 'new_owner' => 28]]);
ok($x['code'] === 401, 'no session: 401');
$x = $rows(['new_owner' => 28]);
ok($x['code'] === 422 && isset($x['json']['error']['fields']['owner']), 'no owner named: 422 on the field');
$x = $rows(['owner' => 31]);
ok($x['code'] === 422 && isset($x['json']['error']['fields']['new_owner']), 'no new owner: 422 on the field');
$x = $rows(['owner' => 31, 'new_owner' => 31]);
ok($x['code'] === 422 && str_contains($x['body'], 'other than'), 'the same person: 422 in words');
$x = $rows(['owner' => 31, 'new_owner' => 999999]);
ok($x['code'] === 422 && isset($x['json']['error']['fields']['new_owner']), 'a new owner who is not here: 422');
$x = $rows(['owner' => 31, 'new_owner' => 28, 'library' => 999999]);
ok($x['code'] === 422 && isset($x['json']['error']['fields']['library']), 'a library that is not here: 422');
$x = $rows(['owner' => 29, 'new_owner' => 28]);
ok($x['code'] === 422 && str_contains($x['body'], 'owns no documents'), 'a person who owns nothing: 422 "owns no documents"');
$x = $rows(['owner' => 31, 'new_owner' => 41]);
ok($x['code'] === 422, 'an agent the application has not admitted (the Watcher) cannot receive: 422 (' . $x['code'] . ')');
$p->exec("UPDATE members SET status = 'inactive' WHERE id = 30");
$x = $rows(['owner' => 31, 'new_owner' => 30]);
$p->exec("UPDATE members SET status = 'active' WHERE id = 30");
ok($x['code'] === 422 && str_contains($x['body'], 'admitted'), 'an inactive new owner: 422 "must be admitted here" (the database says so)');
$x = post_agent(EXPERT, 9001, '/curate/ownership/transfer.php', ['owner' => 31, 'new_owner' => 28]);
ok($x['code'] === 403, 'the expert agent holds no ownership.transfer: 403');
ok($leeLive() === $before, 'nothing moved through all of those (' . $before . ' documents still Lee\'s)');

echo "4. Ownership: a transfer limited to one library\n";
$since = last_activity_id();
$n0 = (int) one("SELECT count(*) FROM notifications WHERE member_id = 28 AND kind = 'ownership_received'");
$x = $rows(['owner' => 31, 'new_owner' => 28, 'library' => $w['lee_lib']]);
ok($x['code'] === 200 && ($x['json']['ok'] ?? false) === true && $x['json']['record_id'] === 28 && $x['json']['documents'] === 4, 'Marco hands Lee\'s four documents of his own library to Bea: ok, record_id = the new owner, 4 moved');
$owner = array_column(q('SELECT id, owner_member_id FROM documents WHERE id = ANY (CAST(:ids AS bigint[]))', ['ids' => '{' . implode(',', array_slice($w['lee_docs'], 0, 4)) . '}']), 'owner_member_id', 'id');
ok(count($owner) === 4 && array_unique(array_values($owner)) === [28], 'the four are Bea\'s now');
ok($leeLive() === 8, 'Lee still owns eight (the Board\'s seven and the loose one): only that library moved');
$a = activity('document.transfer', $since);
$aft = json_decode((string) ($a[0]['after'] ?? '{}'), true);
ok(count($a) === 1 && (int) $a[0]['actor_member_id'] === 27 && $aft['documents'] === 4 && $aft['owner_member_id'] === 28 && (int) json_decode((string) $a[0]['before'], true)['owner_member_id'] === 31 && (int) $a[0]['entity_id'] === 28, 'logged once as document.transfer: by Marco, 31 to 28, with the count 4');
$b = bell(28, 'ownership_received');
ok(count($b) === $n0 + 1 && str_contains($b[0]['title'], '4 documents') && str_contains($b[0]['title'], 'SMOKE Lee'), 'Bea is told: "4 documents of SMOKE Lee are yours now"');
$j = get_json(27, '/curate/ownership?member=31')['json']['data'];
ok($j['owner']['documents'] === 8 && $j['leavers'][0]['documents'] === 8, 'the screen now says eight');

echo "5. Ownership: all of the rest, from a browser; the leaver is gone from the list\n";
$dana0 = (int) one('SELECT count(*) FROM documents WHERE owner_member_id = 30');
$x = post(27, '/curate/ownership/transfer.php', ['owner' => 31, 'new_owner' => 30, 'return_to' => '/curate/ownership']);
ok(in_array($x['code'], [302, 303], true) && str_contains($x['location'], '/curate/ownership') && str_contains($x['location'], 'notice=transferred'), 'a browser POST lands back on the screen with a notice (' . $x['code'] . ')');
ok($leeLive() === 0 && (int) one('SELECT count(*) FROM documents WHERE owner_member_id = 30') === $dana0 + 8, 'Dana owns the eight more');
$j = get_json(27, '/curate/ownership')['json']['data'];
ok($j['leavers'] === [], 'no leaver holds documents any more');
$h = page(actor(27), '/curate/ownership?notice=transferred')['body'];
ok(str_contains($h, 'id="ownership-leavers-empty"') && str_contains($h, 'handed over'), 'the page says nobody who left owns a document, and the notice');
ok(get_json(27, '/curate/')['json']['data']['counts']['ownership'] === 0, 'the index counts zero leavers');
$x = $rows(['owner' => 31, 'new_owner' => 28]);
ok($x['code'] === 422 && str_contains($x['body'], 'owns no documents'), 'handing over again is refused: nothing left');

echo "6. Ownership: who manages afterwards\n";
$pr1 = seed_doc($w['contracts'], 'w9-priya-board-1.pdf', 26, 'Priya\'s on the Board 1.'); $pr2 = seed_doc($w['contracts'], 'w9-priya-board-2.pdf', 26, 'Priya\'s on the Board 2.');
$boardLib = (int) one('SELECT library_id FROM folders WHERE id = :f', ['f' => $w['board_root']]);
$mineBefore = (int) one('SELECT count(*) FROM documents WHERE owner_member_id = 26');
$inBoard = (int) one('SELECT count(*) FROM documents WHERE owner_member_id = 26 AND library_id = :l', ['l' => $boardLib]);
ok(level_of(26, 'document', $pr1) === 'manage' && level_of(30, 'document', $pr1) !== 'manage', 'before: Priya manages her document on the Board (she owns it); Dana does not (' . level_of(30, 'document', $pr1) . ')');
$x = post_json(1, '/curate/ownership/transfer.php', ['owner' => 26, 'new_owner' => 30, 'library' => $boardLib]);
ok($x['code'] === 200 && $x['json']['documents'] === $inBoard && $inBoard >= 2, 'the admin hands Priya\'s ' . $inBoard . ' Board documents to Dana (only that library)');
ok(level_of(26, 'document', $pr1) !== 'manage' && level_of(30, 'document', $pr1) === 'manage' && level_of(30, 'document', $pr2) === 'manage', 'after: Priya no longer manages it (' . level_of(26, 'document', $pr1) . '); Dana does');
ok((int) one('SELECT count(*) FROM documents WHERE owner_member_id = 26') === $mineBefore - $inBoard && (int) one('SELECT owner_member_id FROM documents WHERE id = :d', ['d' => $w['priya_doc']]) === 26, 'her personal-library documents stayed hers');

echo "7. The storage report\n";
$r = get_json(27, '/curate/storage');
$j = $r['json']['data'] ?? [];
as_member(27);
$libs = q('SELECT library_id, used_bytes, documents, versions FROM dc_storage_by_library() ORDER BY used_bytes DESC');
ok($r['code'] === 200 && array_column($j['libraries'], 'library_id') === array_map('intval', array_column($libs, 'library_id')), 'the libraries are dc_storage_by_library\'s, in its order');
ok($j['totals']['used_bytes'] === array_sum(array_map('intval', array_column($libs, 'used_bytes'))) && $j['totals']['documents'] === array_sum(array_map('intval', array_column($libs, 'documents'))) && $j['totals']['versions'] === array_sum(array_map('intval', array_column($libs, 'versions'))), 'the totals are the sums of the rows (used ' . $j['totals']['used_bytes'] . ', ' . $j['totals']['documents'] . ' documents)');
$own = q('SELECT member_id, live_bytes FROM dc_storage_by_owner(50)');
ok(array_column($j['owners'], 'member_id') === array_map('intval', array_column($own, 'member_id')) && $j['owners'][0]['live_bytes'] === (int) $own[0]['live_bytes'], 'the owners, biggest first, are dc_storage_by_owner\'s');
$dup = $j['duplicates'][0] ?? [];
ok(($dup['copies'] ?? 0) === 3 && $dup['wasted_bytes'] === 2 * $dup['byte_size'] && $dup['byte_size'] === 900 && in_array('w8-dup-a.pdf', $dup['names'], true), 'the duplicates: the file kept three times wastes two copies (1,800 bytes)');
$sqlWaste = (int) one('SELECT sum(max_b * (c - 1)) FROM (SELECT max(byte_size) AS max_b, count(*) AS c FROM documents WHERE trashed_at IS NULL AND sha256 IS NOT NULL GROUP BY sha256 HAVING count(*) > 1) t');
ok($j['wasted_bytes'] === $sqlWaste, 'the wasted bytes in all (' . $sqlWaste . ') equal the sum over every duplicated file');
$liveBlobs = (int) one('SELECT count(*) FROM blobs WHERE ref_count > 0 AND deleted_at IS NULL');
ok($j['disk']['blobs_live'] === $liveBlobs && $j['disk']['state'] === 'ok' && !array_key_exists('directory', $j['disk']) && $j['disk']['deduplicated_bytes'] >= 0, 'the disk beside it: ' . $liveBlobs . ' live blobs, the store ok, the directory kept out of the JSON');
$h = page(actor(27), '/curate/storage')['body'];
$miss = missing_ids($h, ['storage-table', 'storage-row-' . $w['lib'], 'storage-total-used', 'storage-total-documents', 'storage-owners', 'duplicates', 'duplicate-0', 'storage-export-btn', 'storage-row-' . $w['lib'] . '-bar']);
ok($miss === [] && str_contains($h, format_bytes_t($j['totals']['used_bytes'])), 'the page: the table with a bar per library (quota 92% on the Board), the totals, the duplicates, the export button' . ($miss ? ' — missing ' . implode(', ', $miss) : ''));
ok(str_contains($h, 'data-status="warning"'), '...the 92% library\'s bar is amber');
ok(get_json(26, '/curate/storage')['code'] === 403 && get_json(29, '/curate/storage')['code'] === 403 && get_json(1, '/curate/storage')['code'] === 200, 'a Member and a guest 403; the admin 200');
$since = last_activity_id(); get_json(27, '/curate/storage');
ok(count(activity('report.storage', $since)) === 1, 'opening it logs report.storage');

echo "8. The storage export\n";
$x = post(27, '/curate/storage/export.php', ['report' => 'storage', 'format' => 'csv']);
ok($x['code'] === 200 && preg_match('/^Content-Type: text\/csv/mi', $x['headers']) === 1 && preg_match('/^Content-Disposition: attachment; filename="doccloud-storage-report-\d{4}-\d{2}-\d{2}\.csv"/mi', $x['headers']) === 1, 'a browser gets a CSV download (text/csv, attachment)');
$csv = ltrim($x['body'], "\xEF\xBB\xBF");
$lines = array_values(array_filter(explode("\r\n", $csv)));
ok(str_starts_with($lines[0], '"section","id","name","kind","documents","versions","used_bytes","quota_bytes","percent"') && count(array_filter($lines, fn ($l) => str_starts_with($l, '"library"'))) === count($libs), 'the header row and one row per library (' . count($libs) . ')');
ok(count(array_filter($lines, fn ($l) => str_starts_with($l, '"duplicate"'))) >= 1 && count(array_filter($lines, fn ($l) => str_starts_with($l, '"owner"'))) === count($own), '...the owners and the duplicates too');
ok(!str_contains($csv, WORLD_SECRET), 'no document\'s words in it');
ok(csv_field('=1+1') === '"\'=1+1"' && csv_field('a"b') === '"a""b"' && csv_field('@x') === '"\'@x"', 'a field that opens as a formula is defused; quotes are doubled');
$since = last_activity_id();
$x = post_json(27, '/curate/storage/export.php', ['report' => 'storage']);
ok($x['code'] === 200 && ($x['json']['ok'] ?? false) && $x['json']['file']['content_type'] === 'text/csv' && $x['json']['file']['rows'] > 0 && str_contains($x['json']['csv'], '"section"'), 'JSON mode: {file: {name, content_type, rows}, csv}');
$x = post_json(27, '/curate/storage/export.php', ['report' => 'search', 'since' => '30d']);
ok($x['code'] === 200 && $x['json']['file']['rows'] === 2 && str_contains($x['json']['csv'], 'budget forecast'), 'the search report as CSV: its two clustered gaps');
ok(count(activity('report.export', $since)) === 2, 'both exports logged report.export');
ok(post_json(26, '/curate/storage/export.php', ['report' => 'storage'])['code'] === 403 && post_json(26, '/curate/storage/export.php', ['report' => 'search'])['code'] === 403, 'a Member: 403 for either report');
$x = post_json(27, '/curate/storage/export.php', ['report' => 'people']);
ok($x['code'] === 422 && isset($x['json']['error']['fields']['report']), 'an unknown report: 422');
$x = post_json(27, '/curate/storage/export.php', ['report' => 'storage', 'format' => 'pdf']);
ok($x['code'] === 422 && isset($x['json']['error']['fields']['format']), 'an unknown format: 422');

echo "9. The search report\n";
$r = get_json(27, '/curate/search');
$j = $r['json']['data'] ?? [];
ok($r['code'] === 200 && $j['days'] === 30, '/curate/search: 200, thirty days by default');
ok(count($j['gaps']) === 2 && $j['gaps'][0]['query'] === 'budget forecast' && $j['gaps'][0]['times'] === 3 && $j['gaps'][1]['query'] === 'zzz nothing here', 'what found nothing, clustered by lower case: "budget forecast" three times (one typed in capitals), then the other');
ok(array_column($j['top'], 'query')[0] === 'budget forecast' && in_array('contract', array_column($j['top'], 'query'), true) && $j['top'][array_search('contract', array_column($j['top'], 'query'), true)]['avg_results'] == 5, 'the top queries, with the average results (contract: 5)');
as_member(27);
$kinds = array_column(q('SELECT kind, count(*) n FROM mcp_search_log GROUP BY kind'), 'n', 'kind');
ok($j['by_kind'] === ['keyword' => (int) $kinds['keyword'], 'graph' => (int) $kinds['graph'], 'name' => (int) $kinds['name']] && $j['searches'] === array_sum($kinds), 'keyword ' . $j['by_kind']['keyword'] . ' · graph ' . $j['by_kind']['graph'] . ' · by name ' . $j['by_kind']['name'] . ': the log\'s own counts');
ok(array_sum(array_column($j['per_day'], 'searches')) === $j['searches'] && array_sum(array_column($j['per_day'], 'empty')) === 4, 'searches a day add up to the total; four found nothing');
$j2 = get_json(27, '/curate/search?since=2d')['json']['data'];
ok($j2['days'] === 2 && count($j2['gaps']) === 2 && $j2['gaps'][0]['times'] === 2 && $j2['searches'] === 6, 'since=2d: only the last two days (budget forecast twice, six searches, not the 3-day-old one)');
ok(get_json(27, '/curate/search?since=90d')['json']['data']['days'] === 90 && get_json(27, '/curate/search?since=2025-01-01')['json']['data']['days'] === 365 && get_json(27, '/curate/search?since=nonsense')['json']['data']['days'] === 30, 'since: 90d, a date (capped at 365 days) and nonsense (30 days)');
$since = last_activity_id();
page(actor(26), '/search/?q=' . rawurlencode('qwertyuiopnothing'));
$j3 = get_json(27, '/curate/search')['json']['data'];
ok(in_array('qwertyuiopnothing', array_column($j3['gaps'], 'query'), true), 'a search Priya just made that found nothing appears in the gaps');
$h = page(actor(27), '/curate/search')['body'];
ok(missing_ids($h, ['search-gaps', 'search-gap-0', 'search-total', 'search-kind-keyword', 'search-kind-graph', 'search-per-day', 'search-top', 'search-range-7d', 'search-range-30d', 'search-range-90d', 'search-export-btn']) === [], 'the page: the gaps table, the totals, the ranges, the export');
ok(get_json(26, '/curate/search')['code'] === 403 && get_json(29, '/curate/search')['code'] === 403, 'a Member and a guest: 403');
ok(count(activity('report.search', $since)) === 2, 'opening it logs report.search (' . count(activity('report.search', $since)) . ' since)');
finish();
function format_bytes_t(int $b): string { $u = ['B', 'KB', 'MB', 'GB', 'TB']; $i = 0; $v = (float) $b; while ($v >= 1024 && $i < 4) { $v /= 1024; $i++; } return ($i === 0 ? (string) $b : number_format($v, 1)) . ' ' . $u[$i]; }
